var AJ = {
  host: function() {
    var h = '';
    try { h = getItem('aj_host', ''); } catch (e) {}
    if (!h) { h = 'https://aishuangju.com'; }
    return h.replace(/\/+$/, '');
  },
  fetch: function(url) {
    var html = '';
    var ua = 'Mozilla/5.0 (Linux; Android 13; SM-S9080) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
    for (var i = 0; i < 2; i++) {
      try {
        html = fetch(url, {headers: {'User-Agent': ua, 'Referer': this.host() + '/'}, timeout: 30000});
        if (html && html.length > 500) { return html; }
      } catch (e) {}
    }
    try { html = fetch(url); } catch (e2) {}
    return html || '';
  },
  hash: function(s) {
    var h = 5381;
    s = String(s || '');
    for (var i = 0; i < s.length; i++) { h = ((h << 5) + h + s.charCodeAt(i)) & 0x7fffffff; }
    return String(h);
  },
  fetchCached: function(url, ttlMin) {
    var key = 'aj_c_' + this.hash(url);
    var now = 0;
    try { now = Math.floor(Date.now() / 1000); } catch (e0) { now = 0; }
    if (now > 0) {
      try {
        var raw = getItem(key, '');
        if (raw) {
          var o = JSON.parse(raw);
          if (o && o.t && o.h && o.h.length > 500 && (now - o.t) < ttlMin * 60) { return o.h; }
        }
      } catch (e1) {}
    }
    var h = this.fetch(url);
    if (h && h.length > 500 && now > 0) {
      try { putItem(key, JSON.stringify({t: now, h: h})); } catch (e2) {}
    }
    return h;
  },
  _pid: 0,
  pic: function(u, pid) {
    var p0 = this.ajPicCached(u);
    if (p0) { return p0; }
    var p = this.ajPic(u);
    if (!p) { return ''; }
    if (p.indexOf('http') === 0) { return ''; }
    return p;
  },
  ajPicCached: function(url) {
    try {
      var u = String(url || '').trim();
      if (!u) { return ''; }
      if (u.indexOf('${') >= 0 || u.indexOf('data.') >= 0 || u.indexOf('{{') >= 0) { return ''; }
      if (u.indexOf('.svg') >= 0) { return ''; }
      if (u.indexOf('//') === 0) { u = 'https:' + u; }
      else if (u.charAt(0) === '/') { u = this.host() + u; }
      else if (u.indexOf('http') !== 0) { u = this.host() + '/' + u.replace(/^\//, ''); }
      var tail = u.substring(u.length - 30).replace(/[^A-Za-z0-9]/g, '');
      var cp = 'hiker://files/aj_' + tail + '.webp';
      if (fileExist(cp)) { return String(getPath(cp)); }
    } catch (e) {}
    return '';
  },
  abs: function(u) {
    if (!u) return '';
    u = String(u).trim();
    if (u.indexOf('//') === 0) { return 'https:' + u; }
    if (u.indexOf('http://') === 0 || u.indexOf('https://') === 0) { return u; }
    if (u.charAt(0) === '/') { return this.host() + u; }
    return this.host() + '/' + u;
  },
  ajPic: function(url) {
    try {
      var u = String(url || '').trim();
      if (!u) { return ''; }
      if (u.indexOf('${') >= 0 || u.indexOf('data.') >= 0 || u.indexOf('{{') >= 0) { return ''; }
      if (u.indexOf('.svg') >= 0) { return ''; }
      if (u.indexOf('//') === 0) { u = 'https:' + u; }
      else if (u.charAt(0) === '/') { u = this.host() + u; }
      else if (u.indexOf('http') !== 0) { u = this.host() + '/' + u.replace(/^\//, ''); }
      var tail = u.substring(u.length - 30).replace(/[^A-Za-z0-9]/g, '');
      var cp = 'hiker://files/aj_' + tail + '.webp';
      try { if (fileExist(cp)) { return String(getPath(cp)); } } catch (e0) {}
      var is = null;
      try { is = fetch(u, { inputStream: true, timeout: 30000, headers: {'Referer': this.host() + '/'} }); } catch (e1) {}
      if (!is) { return u; }
      var baos = new java.io.ByteArrayOutputStream();
      var buf = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 8192);
      var k = 0;
      try { while ((k = is.read(buf, 0, 8192)) > 0) { baos.write(buf, 0, k); } } catch (e2) {}
      var a = baos.toByteArray();
      if (!a || a.length < 100) { return u; }
      var pt = a;
      var b0 = a[0]; if (b0 < 0) { b0 += 256; }
      var b1 = a.length > 1 ? a[1] : 0; if (b1 < 0) { b1 += 256; }
      var plain = (b0 === 0xFF && b1 === 0xD8) || (b0 === 0x89 && b1 === 0x50) || (b0 === 0x52 && b1 === 0x49) || (b0 === 0x47 && b1 === 0x49);
      if (!plain) {
        try {
          var kb = new java.lang.String('2019ysapp7527').getBytes('UTF-8');
          var n = Math.min(100, a.length);
          for (var i = 0; i < n; i++) {
            a[i] = a[i] ^ kb[i % kb.length];
          }
          pt = a;
        } catch (e3) { return u; }
        if (!pt || pt.length < 100) { return u; }
        var q0 = pt[0]; if (q0 < 0) { q0 += 256; }
        var q1 = pt.length > 1 ? pt[1] : 0; if (q1 < 0) { q1 += 256; }
        var ok = (q0 === 0xFF && q1 === 0xD8) || (q0 === 0x89 && q1 === 0x50) || (q0 === 0x52 && q1 === 0x49) || (q0 === 0x47 && q1 === 0x49);
        if (!ok) { return u; }
      }
      try {
        var lp = String(getPath(cp));
        var rp = lp;
        if (rp.indexOf('file://') === 0) { rp = rp.substring(7); }
        else if (rp.indexOf('file:') === 0) { rp = rp.substring(5); }
        var par = rp.substring(0, rp.lastIndexOf('/'));
        var df = new java.io.File(par);
        df.mkdirs();
        var fos = new java.io.FileOutputStream(rp);
        fos.write(pt);
        fos.close();
        return lp;
      } catch (e5) { return u; }
    } catch (e6) { try { return String(url || ''); } catch (e7) { return ''; } }
  },
  clean: function(s) {
    if (!s) return '';
    return String(s).replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/\\u0026/g, '&').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
  },
  myVar: function(k, def) {
    try { return getMyVar(k, def); } catch (e) { return def; }
  },
  putVar: function(k, v) {
    try { putMyVar(k, v); } catch (e) {}
  },
  page: function() {
    var p = 1;
    try { p = parseInt(MY_PAGE || 1, 10) || 1; } catch (e) {}
    var last = 0;
    try { last = parseInt(getMyVar('aj_last_my', '0'), 10) || 0; } catch (e) {}
    if (p <= last) { p = 1; }
    try { putMyVar('aj_last_my', String(p)); } catch (e) {}
    return p;
  },
  kw: function() {
    var k = '';
    try {
      var m = String(MY_URL || '').match(/[?&]kw=([^&#]+)/);
      if (m) { try { k = decodeURIComponent(m[1]); } catch (e) { k = m[1]; } }
    } catch (e) {}
    if (!k) {
      try {
        var m2 = String(MY_URL || '').match(/\/search\/([^\/\?#]+)/);
        if (m2) { try { k = decodeURIComponent(m2[1]); } catch (e) { k = m2[1]; } }
      } catch (e) {}
    }
    if (!k) { k = this.myVar('aj_kw', ''); }
    if (!k) {
      try { if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) { k = String(MY_KEYWORD); } } catch (e) {}
    }
    return String(k || '').trim();
  },
  color: function(key) {
    var c = this.myVar('aj_c_' + key, '');
    return c || '#FFFFFF';
  },
  colorTitle: function(txt, key) {
    var c = this.color(key);
    return '\u2018\u2018\u2019\u2019<b> <font color=' + c + '>' + txt + ' </font></b>';
  },
  sortTitle: function(txt, active) {
    var c = active ? '#FF00FF' : '#FFFFFF';
    return '\u2018\u2018\u2019\u2019<b> <font color=' + c + '>' + txt + ' </font></b>';
  },
  navUrl: function(mid) {
    return $('hiker://empty#noLoading#').lazyRule(function(m) {
      var pal=['#5B8DEF','#9370db','#FF5D50','#FF6699','#5cb85c','#FFA500','#00CED1'];
      var cur=''; try{cur=getMyVar('aj_c_nav_'+m,'');}catch(e){}
      var nc=pal[Math.floor(Math.random()*7)]; var g=0;
      while(nc===cur&&g<10){nc=pal[Math.floor(Math.random()*7)];g++;}
      putMyVar('aj_c_nav_'+m,nc);
      putMyVar('aj_mid', m);
      putMyVar('aj_last_my', '0');
      putMyVar('aj_kw', '');
      putMyVar('aj_sort', '1');
      refreshPage(false);
      return 'hiker://empty';
    }, mid);
  },
  subUrl: function(mid, key, val) {
    return $('hiker://empty#noLoading#').lazyRule(function(m, k, v) {
      var pal=['#5B8DEF','#9370db','#FF5D50','#FF6699','#5cb85c','#FFA500','#00CED1'];
      var cur=''; try{cur=getMyVar('aj_c_'+k,'');}catch(e){}
      var nc=pal[Math.floor(Math.random()*7)]; var g=0;
      while(nc===cur&&g<10){nc=pal[Math.floor(Math.random()*7)];g++;}
      putMyVar('aj_c_'+k,nc);
      putMyVar('aj_mid', m);
      putMyVar(k, v);
      putMyVar('aj_last_my', '0');
      putMyVar('aj_sort', '1');
      refreshPage(false);
      return 'hiker://empty';
    }, mid, key, val);
  },
  sortUrl: function(sk) {
    return $('hiker://empty#noLoading#').lazyRule(function(s) {
      putMyVar('aj_sort', s);
      putMyVar('aj_last_my', '0');
      refreshPage(false);
      return 'hiker://empty';
    }, sk);
  },
  jumpUrl: function(mid, key, val) {
    return $('hiker://empty#noLoading#').lazyRule(function(m, k, v) {
      putMyVar('aj_mid', m);
      putMyVar(k, v);
      putMyVar('aj_last_my', '0');
      refreshPage(false);
      return 'hiker://empty';
    }, mid, key, val);
  },
  jumpUrl2: function(mid, k1, v1, k2, v2) {
    return $('hiker://empty#noLoading#').lazyRule(function(m, a, b, c, e) {
      putMyVar('aj_mid', m);
      putMyVar(a, b);
      putMyVar(c, e);
      putMyVar('aj_last_my', '0');
      refreshPage(false);
      return 'hiker://empty';
    }, mid, k1, v1, k2, v2);
  },
  tagSearchUrl: function(tag) {
    return $('hiker://empty#noLoading#').lazyRule(function(t) {
      putMyVar('aj_kw', t);
      refreshPage(false);
      return 'hiker://empty';
    }, tag);
  },
  nav: function(d) {
    var items = [['首页', 'home'], ['AI成人短剧', 'adult'], ['热门爽剧', 'list'], ['精选主题', 'topics'], ['热播榜单', 'rank']];
    for (var i = 0; i < items.length; i++) {
      var label = items[i][0], mid = items[i][1];
      d.push({title: this.colorTitle(label, 'nav_' + mid), url: this.navUrl(mid), col_type: 'scroll_button', extra: {backgroundColor: '#F2F2F2', lineVisible: false}});
    }
    d.push({title: '', col_type: 'blank_block'});
  },
  renderSearchInput: function(d) {
    var def = this.myVar('aj_kw', '');
    d.push({title: '搜索', desc: '搜短剧、主题、标签', url: $.toString(function() { var kw = String(input || '').trim(); if (!kw) { return 'toast://请输入搜索词'; } try { putMyVar('aj_kw', kw); } catch (e) {} return 'hiker://empty?page=fypage&kw=' + encodeURIComponent(kw) + '#noRecordHistory#@rule=js:$.require("hiker://page/so")'; }), col_type: 'input', extra: {defaultValue: def, onChange: "putMyVar('aj_kw', input)"}});
  },
  banner: function(d, items, rich) {
    items = (items || []).filter(function(x) { return x && x.pic; }).slice(0, 5);
    if (!items.length) { return; }
    try { unRegisterTask('aj_banner'); } catch (e) {}
    try { putMyVar('aj_banneri', '0'); } catch (e) {}
    var it0 = items[0];
    d.push({title: '', img: it0.pic, url: it0.url, col_type: 'pic_1_full', extra: {id: 'aj_bannerpic'}});
    d.push({title: it0.title, desc: it0.desc || '', col_type: 'text_1', extra: {id: 'aj_bantitle'}});
    if (rich && it0.desc) {
      d.push({title: it0.desc, col_type: 'text_2', extra: {id: 'aj_banmeta'}});
      d.push({title: this.dotsHtml(0, items.length), col_type: 'text_2', extra: {id: 'aj_bandots'}});
    }
    try {
      registerTask('aj_banner', 5000, $.toString(function(args) {
        var data = args.data;
        var rich = args.rich;
        if (!data || !data.length) { return; }
        var m = data.length;
        var i = 0;
        try { i = parseInt(getMyVar('aj_banneri', '0'), 10) || 0; } catch (e) {}
        i = i + 1;
        if (i >= m) { i = 0; }
        var it = data[i];
        if (it) {
          try { updateItem('aj_bannerpic', {title: '', img: it.pic, url: it.url, col_type: 'pic_1_full', extra: {id: 'aj_bannerpic'}}); } catch (e2) {}
          try { updateItem('aj_bantitle', {title: it.title, desc: it.desc || '', col_type: 'text_1', extra: {id: 'aj_bantitle'}}); } catch (e3) {}
          if (rich && it.desc) {
            try { updateItem('aj_banmeta', {title: it.desc, col_type: 'text_2', extra: {id: 'aj_banmeta'}}); } catch (e4) {}
            try { updateItem('aj_bandots', {title: it.dotsHtml, col_type: 'text_2', extra: {id: 'aj_bandots'}}); } catch (e6) {}
          }
        }
        try { putMyVar('aj_banneri', String(i)); } catch (e) {}
      }, {data: items, rich: rich ? 1 : 0}));
    } catch (e) {}
  },
  dotsHtml: function(cur, n) {
    var out = [];
    for (var i = 0; i < n; i++) {
      out.push(i === cur ? '<font color="#FF8800">●</font>' : '<font color="#888888">○</font>');
    }
    return '\u2018\u2018\u2019\u2019' + out.join(' ');
  },
  shelf: function(d, title, items, mid, key, val) {
    if (!items || !items.length) { return; }
    d.push({title: '', col_type: 'blank_block'});
    var url = '';
    if (mid) { url = this.jumpUrl(mid, key, val); }
    d.push({title: title, col_type: 'text_2'});
    d.push({title: '查看全部 ↗', url: url, col_type: 'text_2'});
    for (var i = 0; i < items.length; i++) { d.push(items[i]); }
  },
  posterCard: function(block) {
    var href = block.match(/href="(\/detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var title = block.match(/poster-card-title">([^<]+)</);
    if (!title) { return null; }
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
    var eps = block.match(/episode-badge">[\s\S]{0,120}?>([^<]+)</);
    if (!eps) { eps = block.match(/episode-badge">([^<]+)</); }
    var heat = block.match(/poster-card-heat">([^<]+)</);
    if (!heat) { heat = block.match(/home-poster-foot">[\s\S]{0,200}?<span>([^<]*热度[^<]*)<\/span>/); }
    var rank = block.match(/poster-rank-text">([^<]+)</);
    var tag = block.match(/poster-card-tag"[^>]*data-tag-href="([^"]+)"[^>]*>([^<]+)</);
    var desc = [];
    if (rank) { desc.push('第' + this.clean(rank[1]) + '名'); }
    if (eps) { desc.push(this.clean(eps[1])); }
    if (heat) { desc.push(this.clean(heat[1])); }
    var pid = 'aj' + (++this._pid);
    var tagUrl = '';
    if (tag) {
      var tm = tag[1].match(/\/tag-list\/([^\/]+)/);
      if (tm) { tagUrl = this.tagJumpUrl(tm[1], this.clean(tag[2])); }
    }
    return {title: this.clean(title[1]), desc: desc.join(' · ').substring(0, 60), pic: img ? this.pic(this.abs(img[1]), pid) : '', url: this.host() + href[1] + '@rule=js:$.require("hiker://page/erji")', col_type: 'movie_3', extra: {id: pid}, tagUrl: tagUrl};
  },
  posterCards: function(html) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="poster-card');
    for (var i = 1; i < parts.length; i++) {
      var c = this.posterCard(parts[i]);
      if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); }
    }
    return out;
  },
  homePoster: function(block) {
    var href = block.match(/href="(\/detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var title = block.match(/home-poster-title">([^<]+)</);
    if (!title) { return null; }
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
    var corner = block.match(/home-poster-corner[^>]*>([^<]+)</);
    var eps = block.match(/home-poster-ep">([^<]+)</);
    var desc = block.match(/home-poster-desc">([\s\S]{0,300}?)<\/p>/);
    var heat = block.match(/home-poster-foot">[\s\S]{0,300}?<span>([^<]*热度[^<]*)<\/span>/);
    var dparts = [];
    if (corner) { dparts.push(this.clean(corner[1])); }
    if (eps) { dparts.push(this.clean(eps[1])); }
    if (heat) { dparts.push(this.clean(heat[1])); }
    var pid = 'aj' + (++this._pid);
    return {title: this.clean(title[1]), desc: dparts.join(' · '), sub: desc ? this.clean(desc[1]).substring(0, 60) : '', pic: img ? this.pic(this.abs(img[1]), pid) : '', url: this.host() + href[1] + '@rule=js:$.require("hiker://page/erji")', col_type: 'movie_3', extra: {id: pid}};
  },
  homePosters: function(html) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="home-poster');
    for (var i = 1; i < parts.length; i++) {
      var c = this.homePoster(parts[i]);
      if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); }
    }
    return out;
  },
  rankItem: function(block) {
    var href = block.match(/href="(\/detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var name = block.match(/home-rank-name">([^<]+)</);
    if (!name) { return null; }
    var num = block.match(/home-rank-num[^>]*>([^<]+)</);
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
    var desc = block.match(/home-rank-desc">([\s\S]{0,300}?)<\/span>/);
    var heat = block.match(/home-rank-heat[^>]*>([^<]+)</);
    var dparts = [];
    if (num) { dparts.push('第' + this.clean(num[1]) + '名'); }
    if (heat) { dparts.push(this.clean(heat[1])); }
    var pid = 'aj' + (++this._pid);
    return {title: this.clean(name[1]), desc: dparts.join(' · '), sub: desc ? this.clean(desc[1]).substring(0, 60) : '', pic: img ? this.pic(this.abs(img[1]), pid) : '', url: this.host() + href[1] + '@rule=js:$.require("hiker://page/erji")', col_type: 'movie_3', extra: {id: pid}};
  },
  rankItems: function(html) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="home-rank-item"');
    for (var i = 1; i < parts.length; i++) {
      var c = this.rankItem(parts[i]);
      if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); }
    }
    return out;
  },
  featuredItem: function(block) {
    var href = block.match(/href="(\/detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var title = block.match(/data-title="([^"]+)"/);
    if (!title) { title = block.match(/home-featured-caption">([^<]+)</); }
    if (!title) { return null; }
    var desc = block.match(/data-desc="([^"]+)"/);
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
    var corner = block.match(/home-poster-corner[^>]*>([^<]+)</);
    var pid = 'aj' + (++this._pid);
    return {title: this.clean(title[1]), desc: corner ? this.clean(corner[1]) : '', sub: desc ? this.clean(desc[1]).substring(0, 60) : '', pic: img ? this.pic(this.abs(img[1]), pid) : '', url: this.host() + href[1] + '@rule=js:$.require("hiker://page/erji")', col_type: 'movie_3', extra: {id: pid}};
  },
  featuredItems: function(html) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="home-featured-item');
    for (var i = 1; i < parts.length; i++) {
      var c = this.featuredItem(parts[i]);
      if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); }
    }
    return out;
  },
  topicCard: function(block) {
    var href = block.match(/href="(\/topic-detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var title = block.match(/home-playlist-title">([^<]+)</);
    if (!title) { title = block.match(/topic-card__title">([^<]+)</); }
    if (!title) { return null; }
    var desc = block.match(/home-playlist-desc">([\s\S]{0,300}?)<\/p>/);
    if (!desc) { desc = block.match(/topic-card__desc">([\s\S]{0,300}?)<\/p>/); }
    var count = block.match(/home-playlist-count">([^<]+)</);
    if (!count) { count = block.match(/topic-card__count">([^<]+)</); }
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
