    var k = this.kw();
    if (!k) {
      this.banner(d, this.homeHeroes(), false);
      this.renderSearchInput(d);
      for (var i = 0; i < this.HOTTAGS.length; i++) {
        d.push({title: this.HOTTAGS[i], url: this.tagSearchUrl(this.HOTTAGS[i]), col_type: 'text_3'});
      }
      setResult(d);
      return;
    }
    var key = 'search:' + k;
    var base = this.host() + '/search/' + encodeURIComponent(k) + '/';
    if (pg > 1 && this.lastPage(key) > 0 && pg > this.lastPage(key)) { setResult(d); return; }
    var html = this.fetch(this.pageUrl(base, pg));
    if (pg === 1) { this.pageInfo(html, key); }
    var items = this.posterCards(html);
    if (pg === 1) { this.banner(d, this.homeHeroes(), false); this.renderSearchInput(d); }
    for (var i = 0; i < items.length; i++) { d.push(items[i]); }
    setResult(d);
  },
  detail: function(d) {
    var url = String(MY_URL || '');
    var m = url.match(/\/detail\/([^\/\?#]+)/);
    if (!m) { setResult(d); return; }
    var slug = m[1];
    var html = this.fetchCached(this.host() + '/detail/' + slug + '/', 10);
    var title = '';
    var tm = html.match(/<h1[^>]*>([\s\S]{0,150}?)<\/h1>/);
    if (tm) { title = this.clean(tm[1]); }
    var cover = '';
    var cm = html.match(/class="detail-cover[^"]*"[^>]*data-src="([^"]+)"/);
    if (!cm) { cm = html.match(/detail-hero[\s\S]{0,800}?data-src="([^"]+)"/); }
    if (cm) { cover = this.pic(this.abs(cm[1])); }
    var dramaId = '';
    var dm = html.match(/data-drama-id="([^"]+)"/);
    if (dm) { dramaId = dm[1]; }
    var totalEp = '';
    var em = html.match(/data-total-episode="([^"]+)"/);
    if (em) { totalEp = em[1]; }
    var status = '';
    var sm = html.match(/detail-episodes-status">\s*<span>([^<]+)<\/span>/);
    if (sm) { status = this.clean(sm[1]); }
    var tags = [];
    var tagLinks = [];
    var tre = /<a class="detail-tag"[^>]*href="([^"]+)"[^>]*>([^<]+)<\/a>/g;
    var t2;
    while ((t2 = tre.exec(html)) !== null) {
      var th = t2[1];
      var tn = this.clean(t2[2]);
      if (!tn) { continue; }
      var lm = th.match(/^\/list\/([^\/]+)/);
      var gm = th.match(/^\/tag-list\/([^\/]+)/);
      if (lm) { tagLinks.push([tn, this.listJumpUrl(lm[1], tn)]); }
      else if (gm) { tagLinks.push([tn, this.tagJumpUrl(gm[1], tn)]); }
      tags.push(tn);
    }
    var desc = '';
    var dm2 = html.match(/<p class="detail-intro">([\s\S]{0,2000}?)<\/p>/);
    if (dm2) {
      desc = this.clean(dm2[1].replace(/<span class="detail-intro-prefix[^>]*>[^<]*<\/span>/, ''));
    }
    var meta = [];
    if (totalEp) { meta.push('共' + totalEp + '集'); }
    if (status) { meta.push(status); }
    d.push({title: title, desc: meta.join(' · '), pic: cover, url: 'hiker://empty', col_type: 'movie_1_left_pic'});
    for (var i = 0; i < tagLinks.length; i++) {
      d.push({title: '#' + tagLinks[i][0], url: tagLinks[i][1], col_type: 'text_3'});
    }
    if (desc) {
      d.push({title: '简介', col_type: 'text_1'});
      d.push({title: desc, col_type: 'rich_text'});
    }
    var eps = this.episodes(html, slug, dramaId);
    if (eps.length) {
      d.push({title: '', col_type: 'blank_block'});
      d.push({title: '选集（' + eps.length + '集）', col_type: 'text_1'});
      for (var e = 0; e < eps.length; e++) { d.push(eps[e]); }
    }
    var rel = this.relatedItems(html);
    if (rel.length) {
      d.push({title: '', col_type: 'blank_block'});
      d.push({title: '猜你喜欢', col_type: 'text_2'});
      d.push({title: '换一换', url: $('hiker://empty#noLoading#').lazyRule(function() {
        var s = 0;
        try { s = parseInt(getMyVar('aj_rel_seed', '0'), 10) || 0; } catch (e) {}
        try { putMyVar('aj_rel_seed', String(s + 1)); } catch (e2) {}
        refreshPage(false);
        return 'hiker://empty';
      }), col_type: 'text_2'});
      var seed = 0;
      try { seed = parseInt(this.myVar('aj_rel_seed', '0'), 10) || 0; } catch (e3) {}
      var n = rel.length;
      var start = (seed * 6) % n;
      for (var j = 0; j < Math.min(6, n); j++) {
        var rc = rel[(start + j) % n];
        if (rc.imgUrl) { rc.pic = this.pic(rc.imgUrl); }
        d.push(rc);
      }
    }
    setResult(d);
  },
  episodes: function(html, slug, dramaId) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="detail-episode"');
    for (var i = 1; i < parts.length; i++) {
      var b = parts[i];
      var ep = b.match(/data-ep="(\d+)"/);
      if (!ep) { continue; }
      var num = ep[1];
      if (seen[num]) { continue; }
      seen[num] = 1;
      var href = b.match(/href="([^"]*)"/);
      var chap = b.match(/data-chapter-id="([^"]+)"/);
      var pid = b.match(/data-playlet-id="([^"]+)"/);
      var coins = b.match(/data-single-coins="([^"]+)"/);
      var did = (pid && pid[1]) || dramaId || '';
      var cid = chap ? chap[1] : '';
      if (!cid && href && href[1]) {
        var hm = href[1].match(/\/play\/[^\/]+\/(\d+)/);
        if (hm) { cid = hm[1]; }
      }
      var isFree = href && href[1] && href[1].indexOf('/play/') === 0;
      var it = null;
      if (isFree && cid) {
        it = {title: '第' + num + '集', url: this.directPlayUrl(slug, cid, did), col_type: 'text_2'};
      } else {
        var c = coins ? coins[1] : '';
        var label = c ? ('第' + num + '集 · 需金币' + c) : ('第' + num + '集 · 需解锁');
        it = {title: label, url: 'toast://' + label, col_type: 'text_2'};
      }
      out.push([parseInt(num, 10) || 0, it]);
    }
    out.sort(function(a, b) { return a[0] - b[0]; });
    var res = [];
    for (var j = 0; j < out.length; j++) { res.push(out[j][1]); }
    return res;
  },
  directPlayUrl: function(slug, chapterId, dramaId) {
    var host = this.host();
    return $('hiker://empty#noLoading#').lazyRule(function(s, c, p, h) {
      try {
        var ua = 'Mozilla/5.0 (Linux; Android 13; SM-S9080) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
        var api = h + '/api/playlet/chapter/detail?chapterId=' + encodeURIComponent(c) + '&playletId=' + encodeURIComponent(p);
        var txt = '';
        try { txt = fetch(api, {headers: {'User-Agent': ua, 'Referer': h + '/'}}); } catch (e1) {}
        if (!txt) { try { txt = fetch(api); } catch (e2) {} }
        if (txt) {
          var o = null;
          try { o = JSON.parse(txt); } catch (e3) {}
          if (o && o.data) {
            var vu = o.data.videoUrl || '';
            var ok = o.data.canWatch;
            if (vu && ok !== false) {
              var play = '';
              if (vu.indexOf('http://') === 0 || vu.indexOf('https://') === 0) { play = vu; }
              else {
                var path = String(vu).replace(/^\/+/, '');
                if (path.indexOf('h5/m3u8/') === 0) { path = path.slice('h5/m3u8/'.length); }
                play = h + '/h5/m3u8/' + path;
              }
              return play + ';{Referer@' + h + '/}#isVideo=true#';
            }
            if (ok === false) { return 'toast://该集需解锁'; }
          }
        }
      } catch (e4) {}
      return h + '/detail/' + s + '/@ru' + 'le=js:$.require("hiker://page/erji")';
    }, slug, chapterId, dramaId, host);
  },
  relatedCard: function(block) {
    var href = block.match(/href="(\/detail\/[^"\/\?#]+)"/);
    if (!href) { return null; }
    var name = block.match(/detail-related-name">([^<]+)</);
    if (!name) { return null; }
    var img = block.match(/data-src="([^"]+)"/);
    if (!img) { img = block.match(/<img[^>]*src="([^"]+)"/); }
    var sub = block.match(/detail-related-sub">([\s\S]{0,200}?)<\/p>/);
    var meta = block.match(/detail-related-meta">([\s\S]{0,200}?)<\/div>/);
    var pid = 'aj' + (++this._pid);
    var desc = meta ? this.clean(meta[1]).replace(/\s+/g, ' ').substring(0, 40) : '';
    return {title: this.clean(name[1]), desc: desc, pic: '', imgUrl: img ? this.abs(img[1]) : '', url: this.host() + href[1] + '@rule=js:$.require("hiker://page/erji")', col_type: 'movie_3', extra: {id: pid}};
  },
  relatedItems: function(html) {
    var out = [];
    var seen = {};
    var parts = String(html || '').split('<a class="detail-related-item"');
    for (var i = 1; i < parts.length; i++) {
      var c = this.relatedCard(parts[i]);
      if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); }
    }
    return out;
  }
};
var d = [];
var pg = AJ.page();
AJ.search(d, pg);
